import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('register', () => {
    it('throws at registration time for an uncompilable schema naming the tool', () => {
      const registry = new ToolRegistry();
      const invalidSchema = {
        type: 'object',
        properties: {
          location: {type: 'not-a-type'},
        },
      };

      expect(() =>
        registry.register(
          {
            name: 'broken_tool',
            description: 'A tool with a broken schema',
            inputSchema: invalidSchema as any,
          },
          async () => 'unreachable'
        )
      ).toThrow(/broken_tool/);
    });
  });

  describe('execute', () => {
    it('passes valid input through to the executor unchanged', async () => {
      const registry = new ToolRegistry();
      const input = {location: 'London', extra: 'property'};
      let receivedInput: any;

      registry.register(
        {
          name: 'get_weather',
          description: 'Get weather',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        async (inp) => {
          receivedInput = inp;
          return 'sunny';
        }
      );

      await registry.execute('get_weather', input);
      expect(receivedInput).toEqual(input);
    });

    it('rejects wrong-typed fields without leaking values', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'ssn_lookup',
          description: 'SSN lookup',
          inputSchema: {
            type: 'object',
            properties: {ssn: {type: 'string'}},
          },
        },
        async () => 'found'
      );

      const response = await registry.execute('ssn_lookup', {ssn: 12345});
      expect(response.result).toContain('validation failed');
      expect(response.result).toContain('string');
      expect(response.result).not.toContain('12345');
    });

    it('throws for an unknown tool name', async () => {
      const registry = new ToolRegistry();
      await expect(registry.execute('unknown', {})).rejects.toThrow(/Unknown tool: unknown/);
    });

    it('validates against the current schema for function-valued definitions', async () => {
      const registry = new ToolRegistry();
      let schema: any = {type: 'object', properties: {a: {type: 'string'}}};

      registry.register(
        () => ({
          name: 'dynamic',
          description: 'Dynamic schema tool',
          inputSchema: schema,
        }),
        async () => 'ok'
      );

      // First call with first schema
      const res1 = await registry.execute('dynamic', {a: 1});
      expect(res1.result).toContain('validation failed');

      // Update schema
      schema = {type: 'object', properties: {a: {type: 'number'}}};
      const res2 = await registry.execute('dynamic', {a: 1});
      expect(res2.result).toBe('ok');
    });

    it('compiles a static tool schema only once', async () => {
      const registry = new ToolRegistry();
      // We can't easily spy on Ajv.compile here because it's in a closure or internal,
      // but we can at least ensure it works across multiple calls.
      // To truly test "once", we might need a more complex setup or trust the implementation.
      // But the implementation uses a staticValidator property on StoredTool which is set during register.

      let callCount = 0;
      registry.register(
        {
          name: 'static',
          description: 'Static tool',
          inputSchema: {type: 'object'},
        },
        async () => {
          callCount++;
          return 'ok';
        }
      );

      for (let i = 0; i < 10; i++) {
        await registry.execute('static', {});
      }
      expect(callCount).toBe(10);
    });
  });
});

